def table(rr,keys):
 def val(x):return 'N/A' if x is None or x=='' else f'{x:.6f}' if isinstance(x,float) else str(x)
 return '\n'.join(['| '+' | '.join(keys)+' |','| '+' | '.join(['---']*len(keys))+' |']+['| '+' | '.join(val(r.get(k)) for k in keys)+' |' for r in rr])

